:root {
  --ink: #04070f;
  --ink-2: #08101d;
  --paper: #eafcff;
  --muted: #7e95a8;
  --dim: #445666;
  --cyan: #5ff7ff;
  --cyan-hot: #b9fdff;
  --blue: #3d8bff;
  --magenta: #ff3d9a;
  --amber: #ffc65c;
  --green: #6dffb0;
  --danger: #ff4b62;
  --line: rgba(126, 190, 209, 0.18);
  --panel: rgba(6, 14, 26, 0.72);
  --display: "Arial Black", "Helvetica Neue", Impact, sans-serif;
  --sans: "Helvetica Neue", "Segoe UI", Arial, sans-serif;
  --mono: "SFMono-Regular", "Cascadia Code", "Roboto Mono", "Courier New", monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
}

body {
  color: var(--paper);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
  overscroll-behavior: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 3px;
}

.hidden {
  display: none !important;
}

#app {
  position: fixed;
  inset: 0;
  isolation: isolate;
  background: #04070f;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  z-index: 0;
}

body.playing #game {
  cursor: none;
}

/* ── Full-screen atmosphere ───────────────────────────────────── */
.fx-vignette {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 46%, transparent 40%, rgba(0, 3, 9, 0.42) 78%, rgba(0, 2, 6, 0.86) 100%),
    linear-gradient(180deg, rgba(0, 2, 8, 0.3), transparent 15%, transparent 84%, rgba(0, 2, 8, 0.5));
}

.fx-scanlines {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  opacity: 0.15;
  background: repeating-linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.05) 0,
    rgba(255, 255, 255, 0.05) 1px,
    transparent 1px,
    transparent 4px
  );
  mix-blend-mode: overlay;
}

.damage-flash {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(ellipse at center, transparent 30%, rgba(255, 35, 68, 0.5) 100%);
  mix-blend-mode: screen;
}

/* ── Title screen ─────────────────────────────────────────────── */
.menu {
  position: absolute;
  inset: 0;
  z-index: 10;
  display: flex;
  flex-direction: column;
  padding: clamp(20px, 3.2vw, 48px) clamp(22px, 5vw, 76px) clamp(16px, 2.2vw, 32px);
  overflow: hidden;
  transition: opacity 0.45s ease, visibility 0.45s;
}

.menu.closing {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.menu-wash {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(3, 7, 14, 0.96) 0%, rgba(3, 7, 14, 0.88) 27%, rgba(3, 7, 14, 0.58) 49%, rgba(3, 7, 14, 0.08) 73%, rgba(3, 7, 14, 0.42) 100%),
    radial-gradient(ellipse at 76% 46%, rgba(22, 96, 131, 0.14), transparent 48%),
    linear-gradient(180deg, rgba(2, 5, 11, 0.5), transparent 22%, transparent 78%, rgba(2, 5, 11, 0.62));
}

.menu-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  position: relative;
  z-index: 2;
  animation: fade-down 0.8s 0.1s both;
}

.brand {
  display: flex;
  align-items: center;
  gap: 11px;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.22em;
}

.brand-mark {
  width: 24px;
  height: 24px;
  display: flex;
  align-items: flex-end;
  gap: 3px;
  transform: skewX(-13deg);
}

.brand-mark i {
  display: block;
  width: 5px;
  background: var(--cyan);
  box-shadow: 0 0 10px rgba(95, 247, 255, 0.8);
}

.brand-mark i:nth-child(1) { height: 9px; opacity: 0.5; }
.brand-mark i:nth-child(2) { height: 16px; opacity: 0.8; }
.brand-mark i:nth-child(3) { height: 24px; }

.brand-name {
  color: var(--paper);
  font-weight: 700;
}

.brand-tag {
  color: var(--dim);
  padding-left: 12px;
  border-left: 1px solid var(--line);
}

.signal {
  display: flex;
  align-items: center;
  gap: 9px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.16em;
  color: var(--muted);
}

.signal-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 9px var(--green);
  animation: signal-pulse 1.8s infinite;
}

.signal-bars {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 12px;
  margin-left: 3px;
}

.signal-bars i {
  width: 2px;
  background: var(--cyan);
  opacity: 0.65;
}

.signal-bars i:nth-child(1) { height: 3px; }
.signal-bars i:nth-child(2) { height: 5px; }
.signal-bars i:nth-child(3) { height: 8px; }
.signal-bars i:nth-child(4) { height: 12px; }

.menu-body {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(270px, 360px);
  align-items: center;
  gap: clamp(24px, 4vw, 72px);
  position: relative;
  z-index: 2;
  padding: 20px 0;
}

.hero-copy {
  max-width: 780px;
  animation: hero-in 0.85s 0.16s both;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: clamp(16px, 2.4vh, 28px);
  color: var(--cyan);
  font-family: var(--mono);
  font-size: clamp(8px, 0.75vw, 11px);
  font-weight: 600;
  letter-spacing: 0.26em;
}

.eyebrow span {
  width: 34px;
  height: 1px;
  background: var(--cyan);
  box-shadow: 0 0 8px var(--cyan);
}

.game-title {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  font-family: var(--display);
  font-size: clamp(66px, 10.2vw, 156px);
  font-weight: 900;
  line-height: 0.77;
  letter-spacing: -0.058em;
  text-transform: uppercase;
  filter: drop-shadow(0 10px 40px rgba(0, 0, 0, 0.65));
}

.title-line {
  position: relative;
  display: block;
  white-space: nowrap;
}

.title-top {
  color: #f2fdff;
  text-shadow: 0 0 42px rgba(195, 245, 255, 0.18);
}

.title-bottom {
  padding-right: 0.08em;
  color: transparent;
  background: linear-gradient(180deg, #e9feff 0%, #74f8ff 45%, #1d8ca8 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-stroke: 1.5px rgba(163, 250, 255, 0.55);
  text-shadow: 0 0 32px rgba(42, 215, 240, 0.32), 0 0 90px rgba(42, 215, 240, 0.18);
  margin-left: 0.035em;
}

.title-bottom::after {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  color: var(--magenta);
  -webkit-text-stroke: 0;
  background: none;
  opacity: 0;
  clip-path: inset(35% 0 48% 0);
  transform: translateX(-4px);
  animation: title-glitch 7s infinite;
}

.lede {
  margin: clamp(20px, 3vh, 30px) 0 0;
  max-width: 560px;
  color: #a7bcc8;
  font-size: clamp(12px, 1.05vw, 16px);
  line-height: 1.65;
  letter-spacing: 0.015em;
}

.menu-actions {
  display: flex;
  align-items: center;
  gap: clamp(20px, 3vw, 42px);
  margin-top: clamp(24px, 4vh, 42px);
}

.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
  min-height: 58px;
  padding: 0 24px;
  border: 1px solid transparent;
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%);
  transition: transform 0.18s ease, filter 0.18s ease, background 0.18s ease;
}

.btn-primary {
  min-width: clamp(220px, 18vw, 280px);
  justify-content: flex-start;
  color: #021016;
  background: linear-gradient(100deg, #b6fdff 0%, var(--cyan) 52%, #45d9ec 100%);
  box-shadow: 0 0 0 1px rgba(168, 253, 255, 0.38), 0 0 36px rgba(70, 235, 255, 0.24);
}

.btn-primary::before {
  content: "";
  position: absolute;
  inset: 5px;
  border: 1px solid rgba(0, 36, 44, 0.24);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%);
  pointer-events: none;
}

.btn-primary:hover {
  transform: translateY(-2px);
  filter: brightness(1.09);
  box-shadow: 0 0 0 1px rgba(168, 253, 255, 0.55), 0 0 52px rgba(70, 235, 255, 0.36);
}

.btn-primary:active {
  transform: translateY(0);
}

.btn-kicker {
  color: rgba(1, 26, 32, 0.54);
  font-size: 8px;
  letter-spacing: 0.12em;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
}

.btn-label {
  flex: 1;
  text-align: left;
  font-size: 12px;
}

.btn-arrow {
  font-size: 22px;
  font-weight: 400;
  line-height: 1;
  transform: translateY(-1px);
  transition: transform 0.2s;
}

.btn-primary:hover .btn-arrow {
  transform: translate(4px, -1px);
}

.run-spec {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.16em;
  color: var(--dim);
}

.run-spec b {
  color: var(--muted);
  font-size: 12px;
  margin-right: 5px;
  font-weight: 500;
}

.control-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px 22px;
  margin-top: clamp(28px, 4.5vh, 50px);
  padding-top: 18px;
  border-top: 1px solid rgba(126, 190, 209, 0.14);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.15em;
  color: #647b8b;
}

.control {
  display: flex;
  align-items: center;
  gap: 8px;
}

.keys {
  display: flex;
  gap: 2px;
}

kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border: 1px solid rgba(151, 207, 222, 0.26);
  background: rgba(10, 23, 38, 0.6);
  color: #b8d2dc;
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1;
  box-shadow: inset 0 -2px 0 rgba(0, 0, 0, 0.3);
}

kbd.wide {
  min-width: 46px;
}

.mouse-icon {
  width: 14px;
  height: 19px;
  border: 1px solid rgba(151, 207, 222, 0.4);
  border-radius: 7px;
  position: relative;
}

.mouse-icon::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 50%;
  width: 1px;
  height: 5px;
  background: var(--cyan);
  transform: translateX(-50%);
}

.control.auto {
  color: var(--cyan);
}

.pulse-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan);
  animation: signal-pulse 1.4s infinite;
}

/* Title telemetry card */
.telemetry {
  justify-self: end;
  align-self: end;
  width: 100%;
  max-width: 360px;
  margin-bottom: clamp(10px, 3vh, 40px);
  animation: hero-in 0.9s 0.32s both;
}

.telemetry-panel {
  position: relative;
  padding: 18px 20px 16px;
  background: linear-gradient(145deg, rgba(7, 17, 29, 0.78), rgba(4, 10, 20, 0.5));
  border: 1px solid rgba(110, 194, 213, 0.2);
  backdrop-filter: blur(14px);
  clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 18px 100%, 0 calc(100% - 18px));
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.3);
}

.telemetry-panel::before,
.telemetry-panel::after {
  content: "";
  position: absolute;
  width: 24px;
  height: 1px;
  background: var(--cyan);
  opacity: 0.7;
}

.telemetry-panel::before { top: 0; left: 24px; }
.telemetry-panel::after { bottom: 0; right: 24px; }

.telemetry-head {
  display: flex;
  justify-content: space-between;
  padding-bottom: 13px;
  border-bottom: 1px solid var(--line);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.19em;
  color: var(--muted);
}

.live {
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--danger);
}

.live i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--danger);
  box-shadow: 0 0 7px var(--danger);
  animation: signal-pulse 1.2s infinite;
}

.threat-row {
  display: grid;
  grid-template-columns: 30px 1fr auto;
  align-items: center;
  gap: 10px;
  padding: 11px 0;
  border-bottom: 1px solid rgba(126, 190, 209, 0.1);
}

.threat-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  font-size: 13px;
  border: 1px solid currentColor;
  opacity: 0.9;
}

.threat-icon.scout { color: var(--magenta); text-shadow: 0 0 8px var(--magenta); }
.threat-icon.brute { color: var(--amber); text-shadow: 0 0 8px var(--amber); }
.threat-icon.sniper { color: var(--cyan); text-shadow: 0 0 8px var(--cyan); }

.threat-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.threat-copy b {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.14em;
  color: #c4dce4;
}

.threat-copy small {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  color: var(--dim);
}

.threat-code {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.12em;
  color: #4d6574;
}

.best-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  padding-top: 15px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.17em;
  color: var(--dim);
}

.best-row strong {
  color: var(--cyan);
  font-size: 19px;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-shadow: 0 0 18px rgba(95, 247, 255, 0.35);
}

.orbit-caption {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 12px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.16em;
  color: #3f5765;
}

.orbit-caption i {
  width: 22px;
  height: 1px;
  background: #3f5765;
}

.menu-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  position: relative;
  z-index: 2;
  padding-top: 14px;
  border-top: 1px solid rgba(126, 190, 209, 0.1);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.18em;
  color: #405462;
  animation: fade-up 0.8s 0.5s both;
}

.foot-center {
  display: flex;
  align-items: center;
  gap: 12px;
  color: #5e7786;
}

.foot-center i {
  width: 3px;
  height: 3px;
  background: var(--cyan);
  transform: rotate(45deg);
  opacity: 0.6;
}

/* ── HUD ──────────────────────────────────────────────────────── */
.hud {
  position: absolute;
  inset: 0;
  z-index: 6;
  pointer-events: none;
  padding: max(16px, env(safe-area-inset-top)) max(20px, env(safe-area-inset-right)) max(16px, env(safe-area-inset-bottom)) max(20px, env(safe-area-inset-left));
  display: flex;
  flex-direction: column;
  animation: hud-in 0.5s 0.2s both;
}

.hud-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
}

.status-panel,
.wave-panel,
.score-panel {
  position: relative;
  background: linear-gradient(145deg, rgba(7, 16, 28, 0.75), rgba(4, 10, 18, 0.44));
  border: 1px solid rgba(119, 190, 208, 0.19);
  backdrop-filter: blur(10px);
  box-shadow: 0 10px 34px rgba(0, 0, 0, 0.18);
}

.status-panel {
  width: clamp(210px, 21vw, 292px);
  padding: 11px 14px 10px;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 11px), calc(100% - 11px) 100%, 0 100%);
}

.status-panel::before {
  content: "";
  position: absolute;
  top: 0;
  left: 14px;
  width: 38px;
  height: 1px;
  background: var(--cyan);
  box-shadow: 0 0 8px var(--cyan);
}

.status-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.17em;
  color: #82a1b0;
}

.status-head b {
  font-size: 13px;
  font-weight: 500;
  color: var(--cyan);
  letter-spacing: 0.04em;
}

.meter {
  position: relative;
  height: 7px;
  margin-top: 6px;
  background: rgba(122, 179, 195, 0.1);
  overflow: hidden;
}

.meter i {
  display: block;
  height: 100%;
  width: 100%;
  transform-origin: left center;
  background: linear-gradient(90deg, #39c9d8, var(--cyan) 60%, #e5feff);
  box-shadow: 0 0 14px rgba(95, 247, 255, 0.5);
  transition: width 0.18s ease;
}

.meter-ticks {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0, transparent calc(20% - 1px), rgba(4, 9, 15, 0.8) calc(20% - 1px), rgba(4, 9, 15, 0.8) 20%);
  pointer-events: none;
}

.hull-meter i.low {
  background: linear-gradient(90deg, #d62d4d, #ff5b6e);
  box-shadow: 0 0 14px rgba(255, 75, 98, 0.55);
}

.status-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 8px;
}

.mini-meter {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
  max-width: 150px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.14em;
  color: #5c7585;
}

.mini-meter > i {
  flex: 1;
  height: 3px;
  background: rgba(122, 179, 195, 0.12);
  overflow: hidden;
}

.mini-meter b {
  display: block;
  height: 100%;
  width: 100%;
  background: var(--amber);
  box-shadow: 0 0 8px rgba(255, 198, 92, 0.55);
  transition: width 0.1s linear;
}

.overdrive-tag {
  display: none;
  padding: 3px 6px;
  color: #0a1115;
  background: var(--amber);
  font-family: var(--mono);
  font-size: 6px;
  font-weight: 700;
  letter-spacing: 0.12em;
  box-shadow: 0 0 14px rgba(255, 198, 92, 0.45);
  animation: overdrive-blink 0.55s infinite alternate;
}

.overdrive-tag.on { display: block; }

.wave-panel {
  width: clamp(190px, 19vw, 260px);
  padding: 10px 14px 11px;
  text-align: center;
  clip-path: polygon(12px 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 0 100%, 0 12px);
}

.wave-top {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 7px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.2em;
  color: #6e8797;
}

.wave-top strong {
  font-family: var(--display);
  font-size: 24px;
  line-height: 0.9;
  letter-spacing: -0.02em;
  color: var(--paper);
}

.wave-meta {
  display: flex;
  justify-content: space-between;
  margin-top: 7px;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.12em;
  color: #5b7382;
}

.wave-meter {
  height: 3px;
  margin-top: 6px;
}

.wave-meter i {
  background: linear-gradient(90deg, var(--magenta), #ff86b8);
  box-shadow: 0 0 9px rgba(255, 61, 154, 0.5);
  width: 0%;
}

.score-panel {
  width: clamp(185px, 19vw, 270px);
  padding: 10px 12px 9px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 6px 10px;
  clip-path: polygon(0 0, 100% 0, 100% 100%, 11px 100%, 0 calc(100% - 11px));
}

.score-block {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  grid-column: 1 / 2;
  grid-row: 1;
}

.score-block span {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.2em;
  color: #698291;
}

.score-block strong {
  font-family: var(--mono);
  font-size: clamp(18px, 2vw, 27px);
  font-weight: 500;
  letter-spacing: 0.035em;
  line-height: 1.08;
  color: #ecfeff;
  text-shadow: 0 0 16px rgba(95, 247, 255, 0.24);
}

.combo-tag {
  grid-column: 2 / 3;
  grid-row: 1;
  align-self: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 4px 6px;
  border-left: 1px solid var(--line);
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.1em;
  color: #536b7a;
  opacity: 0.55;
  transition: opacity 0.2s, color 0.2s;
}

.combo-tag b {
  font-size: 12px;
  font-weight: 500;
  color: var(--cyan);
}

.combo-tag.hot {
  opacity: 1;
  color: var(--magenta);
}

.combo-tag.hot b {
  color: var(--magenta);
  text-shadow: 0 0 12px rgba(255, 61, 154, 0.7);
}

.hud-buttons {
  grid-column: 1 / 3;
  display: flex;
  justify-content: flex-end;
  gap: 5px;
  pointer-events: auto;
}

.icon-btn {
  min-width: 29px;
  height: 21px;
  padding: 0 6px;
  border: 1px solid rgba(119, 190, 208, 0.18);
  background: rgba(5, 13, 23, 0.5);
  color: #6f8998;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.08em;
  transition: color 0.15s, border-color 0.15s, background 0.15s;
}

.icon-btn:hover {
  color: var(--cyan);
  border-color: rgba(95, 247, 255, 0.45);
  background: rgba(17, 44, 57, 0.5);
}

.icon-btn.muted {
  color: #ff677b;
  border-color: rgba(255, 75, 98, 0.3);
}

.boss-bar {
  align-self: center;
  width: min(560px, 70vw);
  margin-top: 14px;
  padding: 8px 12px 9px;
  background: rgba(12, 5, 14, 0.66);
  border: 1px solid rgba(255, 61, 154, 0.28);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%);
  animation: fade-down 0.3s both;
}

.boss-head {
  display: flex;
  justify-content: space-between;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.2em;
  color: #ff87b6;
}

.boss-head b {
  font-weight: 500;
  color: #ffc0d7;
}

.boss-bar .meter {
  height: 5px;
  margin-top: 5px;
  background: rgba(255, 61, 154, 0.12);
}

.boss-bar .meter i {
  background: linear-gradient(90deg, #8b1e5b, var(--magenta), #ff9dc4);
  box-shadow: 0 0 14px rgba(255, 61, 154, 0.6);
}

.wave-banner {
  position: absolute;
  top: 24%;
  left: 50%;
  width: min(620px, 88vw);
  text-align: center;
  transform: translate(-50%, -10px);
  opacity: 0;
  pointer-events: none;
}

.wave-banner.show {
  animation: banner-in 2.45s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.wave-banner span {
  display: block;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.38em;
  color: var(--cyan);
  text-shadow: 0 0 18px rgba(95, 247, 255, 0.7);
}

.wave-banner strong {
  display: block;
  margin-top: 2px;
  font-family: var(--display);
  font-size: clamp(34px, 5.2vw, 66px);
  line-height: 1;
  letter-spacing: 0.015em;
  color: #effeff;
  text-shadow: 0 0 28px rgba(95, 247, 255, 0.3), 0 4px 30px rgba(0, 0, 0, 0.7);
}

.wave-banner i {
  display: block;
  width: 110px;
  height: 1px;
  margin: 10px auto 0;
  background: linear-gradient(90deg, transparent, var(--cyan), transparent);
  box-shadow: 0 0 10px var(--cyan);
}

.wave-banner.boss span { color: var(--magenta); text-shadow: 0 0 18px rgba(255, 61, 154, 0.7); }
.wave-banner.boss strong { color: #ffe6f0; text-shadow: 0 0 28px rgba(255, 61, 154, 0.4), 0 4px 30px rgba(0, 0, 0, 0.7); }
.wave-banner.boss i { background: linear-gradient(90deg, transparent, var(--magenta), transparent); box-shadow: 0 0 10px var(--magenta); }

.toast {
  position: absolute;
  left: 50%;
  bottom: 16%;
  transform: translate(-50%, 12px);
  padding: 7px 14px;
  border: 1px solid rgba(95, 247, 255, 0.28);
  background: rgba(4, 17, 24, 0.78);
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.18em;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s, transform 0.2s;
  white-space: nowrap;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

.hud-hint {
  position: absolute;
  left: 50%;
  bottom: max(14px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 9px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.13em;
  color: #47606e;
  white-space: nowrap;
}

.hud-hint span {
  display: flex;
  align-items: center;
  gap: 5px;
}

.hud-hint i {
  width: 2px;
  height: 2px;
  border-radius: 50%;
  background: #38505e;
}

.hud-hint kbd {
  height: 16px;
  min-width: 16px;
  font-size: 6px;
  padding: 0 4px;
}

.auto-hint {
  color: #4d8e96;
}

/* ── Touch controls ───────────────────────────────────────────── */
.touch-controls {
  display: none;
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.stick-zone {
  position: absolute;
  bottom: max(22px, env(safe-area-inset-bottom));
  pointer-events: auto;
}

.move-zone { left: max(18px, env(safe-area-inset-left)); }
.aim-zone { right: max(18px, env(safe-area-inset-right)); }

.stick {
  position: relative;
  width: 112px;
  height: 112px;
  border-radius: 50%;
  border: 1px solid rgba(121, 207, 222, 0.26);
  background: radial-gradient(circle at 50% 50%, rgba(10, 28, 40, 0.32), rgba(4, 11, 20, 0.55) 65%);
  box-shadow: inset 0 0 26px rgba(0, 0, 0, 0.35), 0 0 24px rgba(0, 0, 0, 0.22);
  touch-action: none;
}

.stick::before,
.stick::after {
  content: "";
  position: absolute;
  background: rgba(95, 247, 255, 0.12);
}

.stick::before { top: 50%; left: 12%; right: 12%; height: 1px; }
.stick::after { left: 50%; top: 12%; bottom: 12%; width: 1px; }

.stick-rings {
  position: absolute;
  inset: 22px;
  border: 1px solid rgba(95, 247, 255, 0.12);
  border-radius: 50%;
}

.stick-label {
  position: absolute;
  left: 50%;
  bottom: -18px;
  transform: translateX(-50%);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.22em;
  color: #4f6e7d;
}

.stick-knob {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 45px;
  height: 45px;
  margin: -22.5px 0 0 -22.5px;
  border-radius: 50%;
  border: 1px solid rgba(160, 247, 255, 0.55);
  background: radial-gradient(circle at 40% 35%, rgba(126, 250, 255, 0.36), rgba(23, 93, 109, 0.48) 60%, rgba(4, 20, 29, 0.75));
  box-shadow: 0 0 18px rgba(95, 247, 255, 0.16), inset 0 0 12px rgba(95, 247, 255, 0.14);
  transition: transform 0.05s linear;
  will-change: transform;
}

.stick.active {
  border-color: rgba(95, 247, 255, 0.55);
  box-shadow: inset 0 0 26px rgba(0, 0, 0, 0.35), 0 0 26px rgba(95, 247, 255, 0.14);
}

.dash-btn {
  position: absolute;
  right: 114px;
  bottom: 128px;
  width: 62px;
  height: 62px;
  border-radius: 50%;
  border: 1px solid rgba(255, 198, 92, 0.5);
  background: radial-gradient(circle, rgba(74, 50, 15, 0.68), rgba(14, 14, 15, 0.75));
  color: var(--amber);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.13em;
  box-shadow: 0 0 24px rgba(255, 198, 92, 0.12);
  pointer-events: auto;
  touch-action: none;
}

.dash-btn:active {
  transform: scale(0.94);
  background: rgba(255, 198, 92, 0.2);
}

.dash-btn.cooling {
  border-color: rgba(255, 198, 92, 0.16);
  color: rgba(255, 198, 92, 0.32);
}

.dash-btn i {
  position: absolute;
  inset: -1px;
  border-radius: 50%;
  background: conic-gradient(rgba(255, 198, 92, 0.55) calc(var(--ready, 1) * 1turn), transparent 0);
  mask: radial-gradient(circle, transparent 66%, #000 68%);
  -webkit-mask: radial-gradient(circle, transparent 66%, #000 68%);
  pointer-events: none;
}

/* ── Overlays and panels ──────────────────────────────────────── */
.overlay {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background:
    radial-gradient(ellipse at center, rgba(4, 13, 22, 0.55), rgba(1, 4, 9, 0.88) 78%),
    rgba(2, 6, 12, 0.35);
  backdrop-filter: blur(5px);
  animation: overlay-in 0.25s ease both;
}

.panel {
  position: relative;
  width: min(480px, 94vw);
  padding: clamp(28px, 4vw, 44px);
  background: linear-gradient(150deg, rgba(9, 22, 36, 0.96), rgba(3, 9, 17, 0.97));
  border: 1px solid rgba(120, 202, 218, 0.25);
  clip-path: polygon(0 0, calc(100% - 24px) 0, 100% 24px, 100% 100%, 24px 100%, 0 calc(100% - 24px));
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.55), inset 0 0 80px rgba(17, 64, 79, 0.09);
}

.panel::before,
.panel::after {
  content: "";
  position: absolute;
  width: 44px;
  height: 1px;
  background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan);
  opacity: 0.75;
}

.panel::before { top: 0; left: 36px; }
.panel::after { bottom: 0; right: 36px; }

.panel-kicker {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.24em;
  color: var(--cyan);
}

.panel-kicker.danger {
  color: var(--danger);
}

.panel h2 {
  margin-top: 10px;
  font-family: var(--display);
  font-size: clamp(36px, 5vw, 54px);
  line-height: 0.95;
  letter-spacing: -0.02em;
  color: #f2feff;
}

.panel h2 em {
  font-style: normal;
  color: var(--danger);
}

.panel p {
  margin-top: 15px;
  font-size: 12px;
  line-height: 1.6;
  color: #8199a6;
}

.panel-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 28px;
}

.btn.compact {
  min-width: 180px;
  min-height: 50px;
  justify-content: space-between;
}

.btn-ghost {
  min-height: 50px;
  padding: 0 20px;
  border: 1px solid rgba(126, 190, 209, 0.24);
  color: #8da6b2;
  background: rgba(8, 19, 31, 0.4);
}

.btn-ghost:hover {
  border-color: rgba(255, 75, 98, 0.45);
  color: #ff8c9c;
}

.panel-note {
  margin-top: 22px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.15em;
  color: #4f6877;
}

.panel-note kbd {
  height: 17px;
}

.pause-panel {
  width: min(440px, 94vw);
}

/* Upgrade draft */
.upgrade-overlay {
  justify-content: center;
  background:
    radial-gradient(ellipse at 50% 30%, rgba(13, 46, 62, 0.5), transparent 54%),
    rgba(1, 5, 10, 0.86);
  backdrop-filter: blur(7px);
}

.upgrade-head {
  text-align: center;
  margin-bottom: clamp(20px, 3.2vh, 34px);
  animation: fade-down 0.4s both;
}

.upgrade-head h2 {
  margin-top: 8px;
  font-family: var(--display);
  font-size: clamp(30px, 4.2vw, 52px);
  letter-spacing: -0.025em;
  line-height: 1;
  color: #effeff;
}

.upgrade-head h2 em {
  font-style: normal;
  color: var(--cyan);
  text-shadow: 0 0 28px rgba(95, 247, 255, 0.35);
}

.upgrade-head p {
  margin-top: 10px;
  font-size: 11px;
  color: #718b99;
}

.upgrade-cards {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 280px));
  gap: clamp(10px, 1.6vw, 20px);
  width: min(960px, 94vw);
  animation: cards-in 0.55s 0.08s both;
}

.upgrade-card {
  --accent: var(--cyan);
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  min-height: 300px;
  padding: 22px;
  text-align: left;
  background: linear-gradient(155deg, rgba(10, 25, 40, 0.94), rgba(3, 9, 16, 0.95));
  border: 1px solid rgba(123, 195, 211, 0.2);
  clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 0 100%);
  transition: transform 0.2s ease, border-color 0.2s, background 0.2s;
