  function nearestEnemy(x, y, maxDistance = Infinity) {
    let best = null;
    let bestDist = maxDistance;
    for (const enemy of enemies) {
      if (enemy.dead) continue;
      const d = dist(x, y, enemy.x, enemy.y);
      if (d < bestDist) {
