        burst(item.x, item.y, item.type === 'health' ? '#6dffb0' : '#ffc65c', 14, 150, 2.5, 0.5);
        addRing(item.x, item.y, 4, 38, item.type === 'health' ? '#6dffb0' : '#ffc65c', 0.35, 1.5);
        audio.pickup();
        pickups.splice(i, 1);
        updateHUD();
        continue;
      }
      if (item.life <= 0) pickups.splice(i, 1);
    }
