  function drawCrosshair() {
    if (compact || !mouse.active || state.mode !== 'playing') return;
    const overTarget = nearestEnemy(mouse.x, mouse.y, 44);
    const color = overTarget ? '#ff3d9a' : '#8ffcff';
    ctx.save();
