    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(0, 0, 1.7, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = color;
    ctx.globalAlpha = 0.55;
    ctx.beginPath();
    ctx.moveTo(-16, 0); ctx.lineTo(-12, 0);
    ctx.moveTo(12, 0); ctx.lineTo(16, 0);
    ctx.moveTo(0, -16); ctx.lineTo(0, -12);
    ctx.moveTo(0, 12); ctx.lineTo(0, 16);
