function loop(timestamp) {
  const dt = Math.min(0.033, Math.max(0, (timestamp - lastFrame) / 1000));
  lastFrame = timestamp;
  state.time += dt;

  if (state.mode === 'menu') {
    updateMenu(dt);
    drawMenuScene();
  } else if (state.mode === 'playing') {
    updateGame(dt);
    drawGame();
  } else if (state.mode === 'dying') {
    updateDying(dt);
    drawGame();
  } else {
    state.shake = Math.max(0, state.shake - dt * 35);
    state.damageFlash = Math.max(0, state.damageFlash - dt * 2);
    updateEffects(dt, true);
    updateStars(dt, 0.12);
    drawGame();
  }

  requestAnimationFrame(loop);
}

input.newString:
function loop(timestamp) {
  const dt = Math.min(0.05, Math.max(0, (timestamp - lastFrame) / 1000));
  lastFrame = timestamp;
  state.time += dt;

  if (state.mode === 'menu') {
    updateMenu(dt);
  } else if (state.mode === 'playing') {
    updateGame(dt);
  } else if (state.mode === 'dying') {
    updateDying(dt);
  } else {
    state.shake = Math.max(0, state.shake - dt * 35);
    state.damageFlash = Math.max(0, state.damageFlash - dt * 2);
    updateEffects(dt, true);
    updateStars(dt, 0.12);
  }

  if (!window.__voidbreaker?.noDraw) {
    if (state.mode === 'menu') drawMenuScene();
    else drawGame();
  }

  requestAnimationFrame(loop);
}

