import { readFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { join } from 'node:path'

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()

const url = 'http://localhost:3000'
const out = '/tmp/opencode/verify'
const results = []
function check(name, ok, detail = '') {
  results.push({ name, ok, detail })
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${detail ? ' — ' + detail : ''}`)
}

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const errors = []

async function newPage(width, height, touch = false) {
  const page = await browser.newPage({ viewport: { width, height }, hasTouch: touch, isMobile: touch })
  page.setDefaultTimeout(15000)
  page.on('pageerror', (error) => errors.push(error.message))
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()) })
  await page.goto(url, { waitUntil: 'load', timeout: 45000 })
  await page.waitForFunction(() => window.__voidbreaker && window.__voidbreaker.state.mode === 'playing', null, { timeout: 20000 })
  return page
}

async function shot(page, name) {
  await page.screenshot({ path: join(out, name + '.jpg'), type: 'jpeg', quality: 62 })
}

const page = await newPage(1280, 800)
await page.waitForTimeout(900)
const initial = await page.evaluate(() => ({
  mode: __voidbreaker.state.mode,
  wave: __voidbreaker.state.wave,
  enemies: __voidbreaker.enemies.length,
  queue: __voidbreaker.state.spawnQueue.length,
  player: { x: __voidbreaker.player.x, y: __voidbreaker.player.y },
  banner: document.getElementById('waveBanner').classList.contains('show'),
  menuHidden: document.getElementById('menu').classList.contains('hidden'),
  hudVisible: !document.getElementById('hud').classList.contains('hidden'),
  canvas: { w: document.getElementById('game').width, h: document.getElementById('game').height }
}))
check('desktop auto-start', initial.mode === 'playing', JSON.stringify(initial))
check('opening banner visible', initial.banner)
check('menu hidden / HUD visible', initial.menuHidden && initial.hudVisible)
