import { readFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
for (const [name, width, height, touch] of [['menu-desktop', 1280, 800, false], ['menu-mobile', 390, 844, true]]) {
  const page = await browser.newPage({ viewport: { width, height }, hasTouch: touch, isMobile: touch })
  await page.goto('http://localhost:3000', { waitUntil: 'load', timeout: 45000 })
  await page.waitForFunction(() => window.__voidbreaker?.state.mode === 'playing', null, { timeout: 20000 })
  await page.waitForTimeout(400)
  await page.keyboard.press('Escape')
  await page.waitForTimeout(250)
  await page.click('#quitBtn')
  await page.waitForTimeout(900)
  await page.screenshot({ path: `/tmp/opencode/verify/${name}.jpg`, type: 'jpeg', quality: 66 })
  console.log(name, await page.evaluate(() => ({ mode: __voidbreaker.state.mode, menu: !document.getElementById('menu').classList.contains('hidden') })))
  await page.close()
}
await browser.close()

