await d.waitForTimeout(4600)
await d.screenshot({ path: join(out, 'boss3.jpg'), type: 'jpeg', quality: 64 })
console.log('boss', await d.evaluate(() => ({ y: __voidbreaker.state.boss?.y, banner: document.getElementById('waveBanner').classList.contains('show') })))
await d.close()
