async function fps(label) {
  const result = await page.evaluate(async () => {
    let frames = 0
    const start = performance.now()
    await new Promise((resolve) => {
      function tick() {
        frames++
        if (performance.now() - start > 2000) resolve()
        else requestAnimationFrame(tick)
      }
      requestAnimationFrame(tick)
    })
    return { fps: frames / ((performance.now() - start) / 1000), canvas: [document.getElementById('game').width, document.getElementById('game').height], enemies: __voidbreaker.enemies.length, particles: document.querySelectorAll('canvas').length }
  })
  console.log(label, result)
}
await fps('draw')
