import { readFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
await page.goto('http://localhost:3000', { waitUntil: 'load', timeout: 45000 })
await page.waitForFunction(() => window.__voidbreaker?.state.mode === 'playing', null, { timeout: 20000 })
await page.waitForTimeout(1200)
async function fps(label) {
  const result = await page.evaluate(async () => {
    let frames = 0
    const start = performance.now()
    await new Promise((resolve) => {
      function tick() { frames++; if (performance.now() - start > 1400) resolve(); else requestAnimationFrame(tick) }
      requestAnimationFrame(tick)
    })
    return +(frames / ((performance.now() - start) / 1000)).toFixed(1)
  })
  console.log(label, result)
}
await fps('all')
for (const flag of ['__skipBgImage', '__skipStars', '__skipSweep', '__skipArena']) {
  await page.evaluate((flag) => { window[flag] = true }, flag)
  await page.waitForTimeout(300)
  await fps('skip ' + flag.replace('__skip', ''))
  await page.evaluate((flag) => { window[flag] = false }, flag)
}
await browser.close()
